  tile('c_lantern', t => px(t, ['................', '.......##.......', '......#..#......', '.......##.......', '.....######.....', '.....#YYYY#.....', '....#YWWYYY#....', '....#YWYYYY#....', '....#YYYYYY#....', '....#YYYYYY#....', '....#YYYYYY#....', '.....######.....', '................', '................', '................', '................'], { '#': [44, 44, 52], Y: [255, 190, 70], W: [255, 250, 210] }));
