  tile('c_spruce_planks', t => t.each((x, y) => { const row = Math.floor(y / 4), seam = y % 4 === 3 || x === (row * 5 + 2) % 16; t.set(x, y, seam ? [70, 48, 26] : mul([116, 84, 50], 0.9 + 0.08 * Math.sin(x * 0.9 + row * 3) + t.r() * 0.08)); }));
