  const shroom = cap => t => { for (let y = 10; y < 16; y++) { t.set(7, y, [220, 210, 190]); t.set(8, y, [200, 190, 170]); } blob(t, 7.5, 9, 4.2, 2.6, cap, 0.15); if (cap[0] > 180) for (const [x, y] of [[5, 8], [9, 8], [7, 7]]) t.set(x, y, [255, 255, 255]); };
