  if (G.mode === 'survival' && W.difficulty > 0 && W.mobs.some(m => !m.dead && MOBDEF[m.type].hostile && Math.hypot(m.x - t.x - 0.5, m.z - t.z - 0.5) < 8 && Math.abs(m.y - t.y) < 5)) { toast(tr('근처에 몬스터가 있어 잘 수 없어요!')); return; }
